--
-- Table structure for table `dim_drg`
--

DROP TABLE IF EXISTS `dim_drg`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dim_drg` (
  `drg_id` int NOT NULL AUTO_INCREMENT,
  `apr_drg_code` int DEFAULT NULL,
  `apr_drg_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `apr_mdc_code` int DEFAULT NULL,
  `apr_mdc_description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `apr_severity_code` int DEFAULT NULL,
  `apr_severity_description` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `apr_risk_of_mortality` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `apr_medical_surgical` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`drg_id`),
  KEY `idx_drg_nat` (`apr_drg_code`,`apr_mdc_code`,`apr_severity_code`)
) ENGINE=InnoDB AUTO_INCREMENT=5762 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

